// ── Stack — O(1) push/pop using array end ────────────────────
class Stack {
  #data = [];

  push(item) { this.#data.push(item); }        // O(1) amortised
  pop()      { return this.#data.pop(); }      // O(1) strict
  peek()     { return this.#data.at(-1); }     // O(1) strict
  get size() { return this.#data.length; }
  isEmpty()  { return this.#data.length === 0; }
}

// ── Queue — O(1) enqueue/dequeue using linked list ───────────
class QNode {
  constructor(val) { this.val = val; this.next = null; }
}

class Queue {
  #head = null;
  #tail = null;
  #size = 0;

  enqueue(item) {                              // O(1)
    const node = new QNode(item);
    if (!this.#tail) {
      this.#head = this.#tail = node;
    } else {
      this.#tail.next = node;
      this.#tail = node;
    }
    this.#size++;
  }

  dequeue() {                                  // O(1)
    if (!this.#head) return undefined;
    const val = this.#head.val;
    this.#head = this.#head.next;
    if (!this.#head) this.#tail = null;        // queue is now empty
    this.#size--;
    return val;
  }

  peek()     { return this.#head?.val; }
  get size() { return this.#size; }
  isEmpty()  { return this.#size === 0; }
}

// ── Demonstrate both structures ───────────────────────────────
const s = new Stack();
s.push(1); s.push(2); s.push(3);
console.log(s.pop(), s.pop(), s.pop()); // 3 2 1  ← LIFO

const q = new Queue();
q.enqueue('a'); q.enqueue('b'); q.enqueue('c');
console.log(q.dequeue(), q.dequeue(), q.dequeue()); // a b c  ← FIFO

// ── Balanced parentheses: O(n) time, O(n) space ──────────────
function isBalanced(str) {
  const stack = [];
  const pairs = { ')': '(', '}': '{', ']': '[' };

  for (const ch of str) {
    if ('({['.includes(ch)) {
      stack.push(ch);                          // push opener
    } else if (')}]'.includes(ch)) {
      if (stack.length === 0 || stack[stack.length - 1] !== pairs[ch]) {
        return false;                          // no opener or wrong opener
      }
      stack.pop();                             // matched — remove opener
    }
  }
  return stack.length === 0;                   // all openers matched
}

console.log(isBalanced('({[]})'));  // true
console.log(isBalanced('({[}])'));  // false — wrong nesting
console.log(isBalanced('((()'));    // false — unmatched openers remain
console.log(isBalanced(''));        // true — vacuously balanced

// ── Next Greater Element: monotonic stack ────────────────────
// For each element, find the next element to its right that is larger.
function nextGreaterElement(nums) {
  const result = new Array(nums.length).fill(-1);
  const stack = [];  // stores indices of elements awaiting their answer

  for (let i = 0; i < nums.length; i++) {
    // Pop elements whose 'next greater' has been found
    while (stack.length > 0 && nums[i] > nums[stack[stack.length - 1]]) {
      const idx = stack.pop();
      result[idx] = nums[i];
    }
    stack.push(i);
  }
  return result;
}

console.log(nextGreaterElement([2, 1, 5, 3, 4]));
// [5, 5, -1, 4, -1]

// ── BFS with a Queue: level-order traversal ──────────────────
function bfs(graph, start) {
  const visited = new Set([start]);
  const queue   = [start];           // using array as queue for clarity
  const result  = [];

  while (queue.length) {
    const node = queue.shift();      // O(n) — use LinkedList Queue in prod
    result.push(node);
    for (const neighbour of (graph[node] ?? [])) {
      if (!visited.has(neighbour)) {
        visited.add(neighbour);
        queue.push(neighbour);       // enqueue at rear
      }
    }
  }
  return result;
}

// ── DFS with a Stack: depth-first traversal ───────────────────
function dfs(graph, start) {
  const visited = new Set();
  const stack   = [start];
  const result  = [];

  while (stack.length) {
    const node = stack.pop();        // O(1) — LIFO
    if (visited.has(node)) continue;
    visited.add(node);
    result.push(node);
    for (const neighbour of (graph[node] ?? [])) {
      if (!visited.has(neighbour)) stack.push(neighbour);
    }
  }
  return result;
}

// ── Same graph, different structures → different orders ───────
const graph = {
  A: ['B', 'C'],
  B: ['D', 'E'],
  C: ['F'],
  D: [], E: [], F: []
};

console.log('BFS:', bfs(graph, 'A')); // A B C D E F  (level-order)
console.log('DFS:', dfs(graph, 'A')); // A C F B E D  (depth-first)
